CREATE TABLE IF NOT EXISTS institutional_entities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id), legal_name text NOT NULL, entity_code text NOT NULL, entity_type text NOT NULL, purpose text NOT NULL, parent_entity_id uuid REFERENCES institutional_entities(id), ownership_model text, beneficial_ownership_status text NOT NULL DEFAULT 'Unassessed', registration_number text, incorporation_date date, status text NOT NULL DEFAULT 'Proposed', local_governance_required boolean NOT NULL DEFAULT true, evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS entity_governance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid REFERENCES institutional_entities(id) ON DELETE CASCADE, governance_role text NOT NULL, holder_reference text, appointment_basis text, appointment_date date, term_end_date date, authority_scope text, independence_status text, status text NOT NULL DEFAULT 'Proposed');
CREATE TABLE IF NOT EXISTS entity_ownership (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid REFERENCES institutional_entities(id) ON DELETE CASCADE, owner_entity_id uuid REFERENCES institutional_entities(id), owner_reference text, interest_type text NOT NULL, ownership_percentage numeric, voting_percentage numeric, economic_percentage numeric, beneficial_owner_reference text, evidence_reference text, status text NOT NULL DEFAULT 'Unverified');
CREATE TABLE IF NOT EXISTS entity_capital (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid REFERENCES institutional_entities(id) ON DELETE CASCADE, capital_type text NOT NULL, committed_amount numeric, paid_amount numeric, currency text, instrument text, holder_reference text, evidence_reference text, status text NOT NULL DEFAULT 'Proposed');
CREATE TABLE IF NOT EXISTS entity_authority_matrix (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid REFERENCES institutional_entities(id) ON DELETE CASCADE, decision_category text NOT NULL, approval_level text NOT NULL, required_roles text, monetary_threshold numeric, currency text, dual_control_required boolean NOT NULL DEFAULT false, reserved_matter boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'Proposed');
CREATE TABLE IF NOT EXISTS entity_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid REFERENCES institutional_entities(id) ON DELETE CASCADE, asset_reference text NOT NULL, asset_role text NOT NULL, ownership_interest text, custody_model text, ring_fence_status text NOT NULL DEFAULT 'Proposed', evidence_reference text, status text NOT NULL DEFAULT 'Unverified');
CREATE TABLE IF NOT EXISTS entity_compliance_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid REFERENCES institutional_entities(id) ON DELETE CASCADE, compliance_domain text NOT NULL, requirement_summary text NOT NULL, local_owner_role text, group_owner_role text, evidence_reference text, status text NOT NULL DEFAULT 'To Be Assessed', legal_review_required boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS entity_relationships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_entity_id uuid REFERENCES institutional_entities(id) ON DELETE CASCADE, to_entity_id uuid REFERENCES institutional_entities(id) ON DELETE CASCADE, relationship_type text NOT NULL, description text, effective_date date, evidence_reference text, status text NOT NULL DEFAULT 'Proposed');
CREATE TABLE IF NOT EXISTS spv_purposes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid REFERENCES institutional_entities(id) ON DELETE CASCADE, asset_vertical text NOT NULL, project_name text, investment_thesis text, ring_fence_objective text, permitted_activities text, prohibited_activities text, exit_or_wind_down_rule text, community_rights_gate text, status text NOT NULL DEFAULT 'Proposed');
CREATE TABLE IF NOT EXISTS entity_lifecycle_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid REFERENCES institutional_entities(id) ON DELETE CASCADE, event_type text NOT NULL, event_date date NOT NULL DEFAULT current_date, description text NOT NULL, approved_by text, evidence_reference text, status text NOT NULL DEFAULT 'Recorded');
INSERT INTO institutional_entities(jurisdiction_id,legal_name,entity_code,entity_type,purpose,ownership_model,status,local_governance_required) SELECT j.id,'OSANVAULT AFRICA LTD','GROUP-NG','Group Parent','Continental group parent and constitutional governance entity.','Current registered company; ownership evidence to be maintained.','Active','true' FROM jurisdictions j WHERE j.iso_code='NG' AND NOT EXISTS (SELECT 1 FROM institutional_entities WHERE entity_code='GROUP-NG');
INSERT INTO entity_authority_matrix(entity_id,decision_category,approval_level,required_roles,reserved_matter,status) SELECT e.id,'Constitutional / Reserved Matters','Board','Board; applicable shareholders','true','Proposed' FROM institutional_entities e WHERE e.entity_code='GROUP-NG' AND NOT EXISTS (SELECT 1 FROM entity_authority_matrix WHERE entity_id=e.id AND decision_category='Constitutional / Reserved Matters');
INSERT INTO entity_authority_matrix(entity_id,decision_category,approval_level,required_roles,reserved_matter,status) SELECT e.id,'Creation of Subsidiary or SPV','Board','Board; Legal; Finance','true','Proposed' FROM institutional_entities e WHERE e.entity_code='GROUP-NG' AND NOT EXISTS (SELECT 1 FROM entity_authority_matrix WHERE entity_id=e.id AND decision_category='Creation of Subsidiary or SPV');
INSERT INTO entity_authority_matrix(entity_id,decision_category,approval_level,required_roles,reserved_matter,status) SELECT e.id,'Acquisition / Disposal of Protected or Community-Linked Assets','Board + Stewardship Review','Board; Legal; Stewardship; independent review where material','true','Proposed' FROM institutional_entities e WHERE e.entity_code='GROUP-NG' AND NOT EXISTS (SELECT 1 FROM entity_authority_matrix WHERE entity_id=e.id AND decision_category='Acquisition / Disposal of Protected or Community-Linked Assets');